scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 280) @Event280;
	If ($Event == 300) @Event300;
	If ($Event == 310) @Event310;
	If ($Event == 360) @Event360;
	Return;
	
@Event280:
	Say("张琳心：独孤哥哥，事情紧迫，我们还是先上华山吧。", 21);
	Say("独孤剑：好。", 1);
	Return;	
	
@Event300:
	Say("张琳心：这长安城也是几朝古都，可是现在城外却如此萧索。", 21);
	Say("独孤剑：唉，战乱连连，老百姓都逃到南方去了。", 1);
	Return;	
	
@Event310:
	Say("张琳心：我们快去找李三吧！", 21);	
	Return;
	
@Event360:
	Say("张琳心：那方勉肯帮我们说话，看上去也不像坏人，为什么我哥那么讨厌他呢？", 21);
	Say("独孤剑：我也不明白。", 1);
	Return;

traps.trap01.txt:
// 切换到map044石塘镇

	If ($Event == 305) @Event305;

	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map044_石塘镇.map");
	LoadNpc("map044.npc");
	LoadObj("map044.obj");
	SetPlayerPos(7, 8);
	SetPlayerDir(0);
	FadeIn();
	Return;
	
@Event305:
	Say("张如梦：我真的喝醉了，这条好像不是进城的路……", 20);
	Return;

traps.trap02.txt:
// 切换到map049长安城

	If ($Event == 280) @Event280;
	If ($Event == 300) @Event300;
	If ($Event == 304) @Event304;
	If ($Event == 310) @Event310;
	If ($Event == 370) @Event370;

	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map049_长安城.map");
	LoadNpc("map049.npc");
	LoadObj("map049.obj");
	SetPlayerPos(46, 123);
	SetPlayerDir(3);
	FadeIn();
	Return;
	
@Event280:
	Say("张琳心：独孤哥哥，事情紧迫，我们还是先上华山吧。", 21);
	Say("独孤剑：好。", 2);
	Return;

@Event300:
	FadeOut();
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("春潮.mp3");
	LoadMap("map049_长安城.map");
	LoadNpc("map049.npc");
	LoadObj("map049.obj");
	SetPlayerPos(46, 123);
	SetPlayerDir(3);
	FadeIn();
	Say("张琳心：长安城这么大，上哪里去找李三呢？", 21);
	Say("独孤剑：我们四处打听打听吧。", 1);
	Return;	
	Return;

@Event304:
	Return;
	
@Event310:
	Say("张琳心：独孤哥哥，我们快去石塘镇找李三吧！", 21);
	Return;	
	
@Event370:
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map049_长安城.map");
	LoadNpc("map049.npc");
	DelNpc("张琳心.ini",*,*);
	LoadObj("map049.obj");
	SetPlayerPos(46, 123);
	SetPlayerDir(3);
	FadeIn();
	Return;

traps.trap03.txt:
// 在临安城东见到南宫彩虹

	If ($Event == 304) @Event304;
	
	Return;
	
@Event304:
	StopMusic();
	Sleep(500);
	SetNpcDir("黑衣杀手", 3);
	SetNpcDir("南宫彩虹", 3);
	Say("神秘人物：谁？！", 81);
	Say("南宫彩虹：是你？！", 29);
	PlayerGoto(13, 37);
	SetPlayerDir(7);
	Say("张如梦：你果然在这里……", 20);
	Say("南宫彩虹：……", 29);
	Sleep(500);
	NpcGoto("黑衣杀手", 14, 38);
	SetNpcDir("黑衣杀手", 3);
	Say("神秘人物：让我杀了他！", 81);
	Say("南宫彩虹：不必了，你先走吧……这里我会处理的。", 29);
	SetNpcDir("黑衣杀手", 7);
	Say("神秘人物：是！堂主，我先走了。", 81);
	
	
	PlayMusic("情剑.mp3");
	NpcGoto("黑衣杀手", 13, 56);
	DelNpc("黑衣杀手");
	SaveNpc();
	
	SetNpcDir("南宫彩虹", 7);
	Say("南宫彩虹：你从临安千里迢迢跟着我到这里，到底是为了什么？", 30);
	PlayerGoto(14, 38);
	SetPlayerDir(7);
	Say("张如梦：是为了……图！告诉我，图，图在哪里？", 20);
	Say("南宫彩虹：我不明白你在说什么！", 29);
	Say("张如梦：你为什么要从临安跑到这里来？不会……是为了躲开我吧？", 20);
	SetNpcDir("南宫彩虹", 3);
	Say("南宫彩虹：张如梦，你也未免太抬举自己了！我不知道你在说什么，我要走了，请自便！", 29);
	NpcGoto("南宫彩虹", 8, 28);
	DelNpc("南宫彩虹");
	SaveNpc();
	SetPlayerDir(3);
	Say("张如梦：我，我做了什么？她为什么……", 20);
	Sleep(1000);
	Say("张如梦：不行，我要去春花秋月楼，向她解释清楚……", 20);
	SetMapTrap(1, "trap01.txt");
	SetMapTrap(2, "trap02.txt");
	SetMapTrap(3, "");
	Assign($Event, 305);
	Memo("张如梦出了酒楼来到城东，发现南宫彩虹和一个神秘人在一起，酒醉的张如梦出言不逊，南宫彩虹一怒之下离去。");
	Memo("张如梦决定赶去妓院向南宫彩虹解释。");
	Return;
